    gap: 10px;
    padding-bottom: 6px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);}
.bzf-drawer-head .briizify-logo {
    margin-right: auto;}
.bzf-steps {
    display: inline-flex;
    align-items: center;
    gap: 4px;}
.bzf-pip {
    display: inline-flex;
    align-items: center;
    width: 18px;
    height: 12px;
    padding: 0;
    border: none;
    border-radius: 4px;
    background: transparent;
    cursor: pointer;}
.bzf-pip:disabled {
    cursor: default;}
.bzf-pip-fill {
    width: 100%;
    height: 2px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.18);
    transition: background var(--layout-transition-fast, 0.15s ease), height 140ms ease, box-shadow 140ms ease;}
.bzf-pip.done .bzf-pip-fill {
    background: color-mix(in srgb, var(--bzf-orange) 68%, transparent);}
.bzf-pip.active .bzf-pip-fill {
    height: 3px;
    background: var(--bzf-warn);
    box-shadow: 0 0 8px color-mix(in srgb, var(--bzf-warn) 62%, transparent);}
.bzf-pip.skipped .bzf-pip-fill {
    background: repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.24) 0 2px, transparent 2px 5px);}
.bzf-pip:not(:disabled):hover .bzf-pip-fill {
    background: color-mix(in srgb, var(--bzf-warn) 55%, transparent);}
.bzf-pip:focus-visible {
    outline: 2px solid color-mix(in srgb, var(--bzf-glow) 72%, white);
    outline-offset: 1px;}
.bzf-close {
    border: none;
    background: transparent;
    color: var(--bzf-text-muted);
    font-size: 13px;
    cursor: pointer;}
.bzf-close:hover {
