    animation: bzf-step-in 260ms cubic-bezier(0.22, 1, 0.36, 1) both;}
@keyframes bzf-step-in {
    from {
        opacity: 0;
        transform: translateX(16px);
}    to {
        opacity: 1;
        transform: none;
    }}
