.bzf-range-handle {
    position: absolute;
    top: -9px;
    bottom: -9px;
    width: 26px;
    margin-left: -13px;
    padding: 0;
    border: none;
    background: transparent;
    cursor: ew-resize;
    z-index: 3;
    touch-action: none;
    user-select: none;
    -webkit-user-select: none;
    -webkit-app-region: no-drag;
