/* ============================================================
   Floater Shell = FW.
============================================================ */
:root {
    --fw-accent: var(--palette-accent-primary, #00e5e5);
    --fw-surface: var(--fw-surface-override, rgba(7, 17, 24, 0.82));
    --fw-edge: var(--layout-border-color, rgba(0, 229, 229, 0.28));
    --fw-text: var(--ui-text-primary, #d9e8e4);
    --fw-text-soft: var(--palette-text-soft, #9fb3ad);
    --fw-radius: 0.28rem 0.8rem 0.8rem 1.35rem;
    --fw-capsule-radius: 40px;
    --fw-blur: 14px;}
/* ---------- Float window frame ---------- */
.fw {
    position: fixed;
    display: flex;
    flex-direction: column;
    min-width: 320px;
    min-height: 220px;
    background: var(--fw-surface);
    border: 1px solid var(--fw-edge);
    border-radius: var(--fw-radius);
    box-shadow: 0 10px 36px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(var(--fw-blur)) saturate(1.15);
    -webkit-backdrop-filter: blur(var(--fw-blur)) saturate(1.15);
    color: var(--fw-text);
    transition: border-color 0.25s ease, box-shadow 0.25s ease;
    animation: fwIn 0.4s cubic-bezier(0.16, 1, 0.3, 1);}
.fw.is-focused {
    border-color: color-mix(in srgb, var(--fw-accent) 60%, transparent);
    box-shadow: 0 14px 44px rgba(0, 0, 0, 0.5), 0 0 22px color-mix(in srgb, var(--fw-accent) 14%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.07);}
.fw.is-filled {
    border-radius: 0.6rem;}
@keyframes fwIn {
    from {
        opacity: 0;
        transform: scale(0.94) translateY(14px);
}    to {
        opacity: 1;
        transform: scale(1) translateY(0);
    }}
/* Detached capsule titlebar (v3 language) */
.fw-titlebar {
    position: absolute;
    top: -14px;
    left: 10px;
    height: 28px;
    max-width: calc(100% - 20px);
    min-width: min(62%, 340px);
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 0 12px;
    border-radius: var(--fw-capsule-radius);
    background: var(--ui-header-bg, rgba(0, 0, 0, 0.92));
    border: 1px solid color-mix(in srgb, var(--fw-accent) 70%, transparent);
    cursor: grab;
    z-index: 3;
    overflow: hidden;
    user-select: none;
    -webkit-user-select: none;}
.fw-titlebar::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(45deg, transparent 32%, color-mix(in srgb, var(--fw-accent) 26%, transparent) 50%, transparent 68%);
    border-radius: inherit;
    pointer-events: none;}
.fw-titlebar:active {
    cursor: grabbing;}
.fw-title {
    flex: 1;
    min-width: 0;
    font-family: var(--ui-font-main, Chillax), sans-serif;
    font-size: 0.72rem;
    font-weight: 400;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: var(--fw-text);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    pointer-events: none;
    position: relative;}
.fw-btn {
    position: relative;
