/* ---------- Floating dock ---------- */
.fdock {
    position: fixed;
    bottom: 14px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 1100;
    display: flex;
    align-items: center;
    gap: 8px;
    height: var(--fdock-height, 52px);
    max-width: min(92vw, 880px);
    padding: 0 12px 0 6px;
    border-radius: calc(var(--fw-capsule-radius) - 30px);
    background: linear-gradient(180deg, color-mix(in srgb, var(--fw-accent) 16%, transparent), rgba(8, 18, 26, 0.55) 24%, rgba(0, 0, 0, 0.5));
    border: 1.5px solid color-mix(in srgb, var(--fw-accent) 45%, transparent);
    backdrop-filter: blur(10px) saturate(0.9);
    -webkit-backdrop-filter: blur(10px) saturate(0.9);
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.04) inset, 0 6px 30px rgba(0, 0, 0, 0.5), 0 0 40px color-mix(in srgb, var(--fw-accent) 10%, transparent);
    animation: fdockIn 0.7s cubic-bezier(0.16, 1, 0.3, 1);
    width: 68px;
    overflow: hidden;}
@keyframes fdockIn {
    from {
        opacity: 0;
        transform: translateX(-50%) translateY(48px) scale(0.9);
}    to {
        opacity: 1;
        transform: translateX(-50%) translateY(0) scale(1);
    }}
.fdock-scroll {
    display: flex;
    align-items: center;
    gap: 2px;
    overflow-x: auto;
    scrollbar-width: none;
    padding: 0 2px;}
.fdock-scroll::-webkit-scrollbar {
    display: none;}
.fdock-item {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-width: 40px;
    height: 40px;
    padding: 0 10px;
    border-radius: 12px;
    border: none;
    background: transparent;
    color: var(--fw-text-soft);
    cursor: pointer;
    white-space: nowrap;
    flex-shrink: 0;
    font-family: SF Pro Display, SF Pro Symbols, 'Apple Symbols', sans-serif !important;
    transition: background 0.18s ease, color 0.18s ease;}
.fdock-item:hover {
    background: color-mix(in srgb, var(--fw-accent) 10%, transparent);
    color: var(--fw-text);}
.fdock-item:active {
    transform: scale(0.94);}
.fdock-item.on {
    background: color-mix(in srgb, var(--fw-accent) 14%, transparent);
    color: var(--fw-text);
    border-bottom: 2px solid var(--fw-accent);
    border-radius: 12px 12px 4px 4px;}
.fdock-glyph {
    font-size: 17px;
