    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1);}
/* The icon is the resting state; the name fades in under it on hover,
   mirroring the header dock's .cb-label behaviour. Absolutely positioned so
   the dock keeps its height and nothing shifts. */
.fdock-label {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 3px;
    text-align: center;
    font-size: 0.5rem;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    opacity: 0;
    transform: translateY(4px);
    pointer-events: none;
    user-select: none;
    transition: opacity 0.2s ease, transform 0.2s ease;}
.fdock-item:hover .fdock-glyph,
.fdock-item:focus-visible .fdock-glyph {
    transform: translateY(-6px);}
.fdock-item:hover .fdock-label,
.fdock-item:focus-visible .fdock-label {
    opacity: 1;
    transform: translateY(0);}
.fdock-canvases-wrap {
    position: relative;
    display: inline-flex;
    flex-shrink: 0;}
.fdock-side {
    display: flex;
    align-items: center;
    gap: 10px;
